-- scripts/build20_check2.sql (build 20): check 2 (a)-(m) per CLAUDE.md section 9 for DAVIDSON; (m) is the HERSHA_X_DAVIDSON cross-lane rule. Read-only. Every count must be 0.
select 'a' c, count(*) n from (select source_site_code, department, account_key, record_type from DEV_G2M_AI.XREF_SNAPSHOT.XREF_ACCOUNT_CLASSIFICATION where source_lane='DAVIDSON' group by all having count(*)>1)
union all
select 'b', count_if(h1 is null or source_site_code is null or department is null or account_key is null or record_type is null) from DEV_G2M_AI.XREF_SNAPSHOT.XREF_ACCOUNT_CLASSIFICATION where source_lane='DAVIDSON'
union all
select 'c', count(*) from (select source_site_code, department, account_key, record_type from DEV_G2M_AI.STAGING.STG_DAVIDSON_HOTEL_MONTHLY_REPORT union all select source_site_code, department, account_key, record_type from DEV_G2M_AI.STAGING.STG_DAVIDSON_FULL_YEAR_PL union all select source_site_code, department, account_key, record_type from DEV_G2M_AI.STAGING.STG_DAVIDSON_HOTEL_BUDGET) s where not exists (select 1 from DEV_G2M_AI.XREF_SNAPSHOT.XREF_ACCOUNT_CLASSIFICATION x where x.source_lane='DAVIDSON' and x.source_site_code=coalesce(nullif(trim(s.source_site_code),''),'~BLANK~') and x.department=coalesce(nullif(trim(s.department),''),'~BLANK~') and x.account_key=coalesce(nullif(trim(s.account_key),''),'~BLANK~') and x.record_type=coalesce(nullif(trim(s.record_type),''),'~BLANK~'))
union all
select 'd', count(*) from (select source_site_code, department, account_key, record_type from DEV_G2M_AI.XREF_SNAPSHOT.XREF_ACCOUNT_CLASSIFICATION where source_lane='DAVIDSON' group by all having count(distinct metric_unit)>1 or count(distinct aggregation_type)>1)
union all
select 'e', (select count(*) from DEV_G2M_AI.TRANSFORMATION.XFRM_DAVIDSON_INCOME_STATEMENT where h1 is null or h1 not in ('Revenue','Expense','Below the Line','Allocations & Reserves')) + (select count(*) from DEV_G2M_AI.TRANSFORMATION.XFRM_DAVIDSON_BALANCE_SHEET where h1 is null or h1<>'Balance Sheet') + (select count(*) from DEV_G2M_AI.TRANSFORMATION.XFRM_DAVIDSON_OPERATING_METRICS where h1 is null or h1<>'Statistic') + (select count(*) from DEV_G2M_AI.TRANSFORMATION.XFRM_DAVIDSON_UNKNOWN where h1 in ('Revenue','Expense','Below the Line','Allocations & Reserves','Balance Sheet','Statistic') and coalesce(unknown_reason,'')<>'DUPLICATE_DETAIL')
union all
select 'f', (select count(*) from DEV_G2M_AI.XREF_SNAPSHOT.XREF_ACCOUNT_CLASSIFICATION where source_lane='DAVIDSON' and h1='Statistic' and value_sign is not null) + (select count(*) from DEV_G2M_AI.TRANSFORMATION.XFRM_DAVIDSON_OPERATING_METRICS where value_sign is not null)
union all
select 'h', (select count(*) from DEV_G2M_AI.TRANSFORMATION.XFRM_DAVIDSON_INCOME_STATEMENT where source_amount is not null and value_sign is not null and (value is null or abs(value-source_amount*value_sign)>0.005)) + (select count(*) from (select value, value_sign from DEV_G2M_AI.SEMANTIC.SEM_AI_INCOME_STATEMENT_ACTUAL where source_lane='DAVIDSON' union all select value, value_sign from DEV_G2M_AI.SEMANTIC.SEM_AI_INCOME_STATEMENT_BUDGET where source_lane='DAVIDSON' union all select value, value_sign from DEV_G2M_AI.SEMANTIC.SEM_AI_INCOME_STATEMENT_FORECAST where source_lane='DAVIDSON') where value is not null and value_sign is null)
union all
select 'g', count_if(category is distinct from 'ACTUAL') from DEV_G2M_AI.SEMANTIC.SEM_AI_INCOME_STATEMENT_ACTUAL where source_lane='DAVIDSON'
union all
select 'g', count_if(category is distinct from 'BUDGET') from DEV_G2M_AI.SEMANTIC.SEM_AI_INCOME_STATEMENT_BUDGET where source_lane='DAVIDSON'
union all
select 'g', count_if(category is distinct from 'FORECAST') from DEV_G2M_AI.SEMANTIC.SEM_AI_INCOME_STATEMENT_FORECAST where source_lane='DAVIDSON'
union all
select 'i', count_if(source_table is null) from DEV_G2M_AI.SEMANTIC.SEM_AI_INCOME_STATEMENT_ACTUAL where source_lane='DAVIDSON'
union all
select 'i', count_if(source_table is null) from DEV_G2M_AI.SEMANTIC.SEM_AI_INCOME_STATEMENT_BUDGET where source_lane='DAVIDSON'
union all
select 'i', count_if(source_table is null) from DEV_G2M_AI.SEMANTIC.SEM_AI_INCOME_STATEMENT_FORECAST where source_lane='DAVIDSON'
union all
select 'i', count_if(source_table is null) from DEV_G2M_AI.SEMANTIC.SEM_AI_BALANCE_SHEET where source_lane='DAVIDSON'
union all
select 'i', count_if(source_table is null) from DEV_G2M_AI.SEMANTIC.SEM_AI_OPERATING_METRICS where source_lane='DAVIDSON'
union all
select 'i', count_if(source_table is null) from DEV_G2M_AI.SEMANTIC.SEM_AI_UNKNOWN where source_lane='DAVIDSON'
union all
select 'j', count_if((unknown_reason in ('UNRESOLVED_CATEGORY','BOTH') and unresolved_category_value is null) or (coalesce(unknown_reason,'') not in ('UNRESOLVED_CATEGORY','BOTH') and unresolved_category_value is not null) or unknown_reason is null or unknown_reason not in ('UNCLASSIFIED_ACCOUNT','UNRESOLVED_CATEGORY','BOTH','SOURCE_ROLLUP','PLANNING_INPUT','DUPLICATE_DETAIL')) from DEV_G2M_AI.SEMANTIC.SEM_AI_UNKNOWN where source_lane='DAVIDSON'
union all
select 'k', count_if((h.h2 is not null and (x.p_l_section is distinct from h.sec or x.normal_balance is distinct from h.bal)) or (h.h2 is null and (x.p_l_section is not null or x.normal_balance is not null))) from DEV_G2M_AI.XREF_SNAPSHOT.XREF_ACCOUNT_CLASSIFICATION x left join (select * from values ('Revenue','Gross Profit','Credit'),('Cost of Goods Sold','Gross Profit','Debit'),('Payroll','Operating','Debit'),('Operating Expenses','Operating','Debit'),('Depreciation & Amortization','Operating','Debit'),('Other Income / (Expense)','Non-Operating','Mixed'),('Income Taxes','Non-Operating','Debit') v(h2,sec,bal)) h on h.h2=x.h2 where x.source_lane='DAVIDSON'
union all
select 'k', count_if((h.h2 is not null and (x.p_l_section is distinct from h.sec or x.normal_balance is distinct from h.bal)) or (h.h2 is null and (x.p_l_section is not null or x.normal_balance is not null))) from DEV_G2M_AI.SEMANTIC.SEM_AI_INCOME_STATEMENT_ACTUAL x left join (select * from values ('Revenue','Gross Profit','Credit'),('Cost of Goods Sold','Gross Profit','Debit'),('Payroll','Operating','Debit'),('Operating Expenses','Operating','Debit'),('Depreciation & Amortization','Operating','Debit'),('Other Income / (Expense)','Non-Operating','Mixed'),('Income Taxes','Non-Operating','Debit') v(h2,sec,bal)) h on h.h2=x.h2 where x.source_lane='DAVIDSON'
union all
select 'k', count_if((h.h2 is not null and (x.p_l_section is distinct from h.sec or x.normal_balance is distinct from h.bal)) or (h.h2 is null and (x.p_l_section is not null or x.normal_balance is not null))) from DEV_G2M_AI.SEMANTIC.SEM_AI_INCOME_STATEMENT_BUDGET x left join (select * from values ('Revenue','Gross Profit','Credit'),('Cost of Goods Sold','Gross Profit','Debit'),('Payroll','Operating','Debit'),('Operating Expenses','Operating','Debit'),('Depreciation & Amortization','Operating','Debit'),('Other Income / (Expense)','Non-Operating','Mixed'),('Income Taxes','Non-Operating','Debit') v(h2,sec,bal)) h on h.h2=x.h2 where x.source_lane='DAVIDSON'
union all
select 'k', count_if((h.h2 is not null and (x.p_l_section is distinct from h.sec or x.normal_balance is distinct from h.bal)) or (h.h2 is null and (x.p_l_section is not null or x.normal_balance is not null))) from DEV_G2M_AI.SEMANTIC.SEM_AI_INCOME_STATEMENT_FORECAST x left join (select * from values ('Revenue','Gross Profit','Credit'),('Cost of Goods Sold','Gross Profit','Debit'),('Payroll','Operating','Debit'),('Operating Expenses','Operating','Debit'),('Depreciation & Amortization','Operating','Debit'),('Other Income / (Expense)','Non-Operating','Mixed'),('Income Taxes','Non-Operating','Debit') v(h2,sec,bal)) h on h.h2=x.h2 where x.source_lane='DAVIDSON'
union all
select 'k', count_if((h.h2 is not null and (x.p_l_section is distinct from h.sec or x.normal_balance is distinct from h.bal)) or (h.h2 is null and (x.p_l_section is not null or x.normal_balance is not null))) from DEV_G2M_AI.SEMANTIC.SEM_AI_BALANCE_SHEET x left join (select * from values ('Revenue','Gross Profit','Credit'),('Cost of Goods Sold','Gross Profit','Debit'),('Payroll','Operating','Debit'),('Operating Expenses','Operating','Debit'),('Depreciation & Amortization','Operating','Debit'),('Other Income / (Expense)','Non-Operating','Mixed'),('Income Taxes','Non-Operating','Debit') v(h2,sec,bal)) h on h.h2=x.h2 where x.source_lane='DAVIDSON'
union all
select 'k', count_if((h.h2 is not null and (x.p_l_section is distinct from h.sec or x.normal_balance is distinct from h.bal)) or (h.h2 is null and (x.p_l_section is not null or x.normal_balance is not null))) from DEV_G2M_AI.SEMANTIC.SEM_AI_OPERATING_METRICS x left join (select * from values ('Revenue','Gross Profit','Credit'),('Cost of Goods Sold','Gross Profit','Debit'),('Payroll','Operating','Debit'),('Operating Expenses','Operating','Debit'),('Depreciation & Amortization','Operating','Debit'),('Other Income / (Expense)','Non-Operating','Mixed'),('Income Taxes','Non-Operating','Debit') v(h2,sec,bal)) h on h.h2=x.h2 where x.source_lane='DAVIDSON'
union all
select 'k', count_if((h.h2 is not null and (x.p_l_section is distinct from h.sec or x.normal_balance is distinct from h.bal)) or (h.h2 is null and (x.p_l_section is not null or x.normal_balance is not null))) from DEV_G2M_AI.SEMANTIC.SEM_AI_UNKNOWN x left join (select * from values ('Revenue','Gross Profit','Credit'),('Cost of Goods Sold','Gross Profit','Debit'),('Payroll','Operating','Debit'),('Operating Expenses','Operating','Debit'),('Depreciation & Amortization','Operating','Debit'),('Other Income / (Expense)','Non-Operating','Mixed'),('Income Taxes','Non-Operating','Debit') v(h2,sec,bal)) h on h.h2=x.h2 where x.source_lane='DAVIDSON'
union all
select 'l', count_if((normal_balance='Credit' and value_sign is distinct from 1) or (normal_balance='Debit' and value_sign is distinct from -1)) from DEV_G2M_AI.XREF_SNAPSHOT.XREF_ACCOUNT_CLASSIFICATION where source_lane='DAVIDSON'
union all
select 'm', count(*) from (select source_lane, source_site_code, period_end, category from DEV_G2M_AI.SEMANTIC.SEM_AI_INCOME_STATEMENT_ACTUAL where source_lane='HERSHA' and source_site_code in ('149','230') and year(period_end)=2026 union all select source_lane, source_site_code, period_end, category from DEV_G2M_AI.SEMANTIC.SEM_AI_INCOME_STATEMENT_BUDGET where source_lane='HERSHA' and source_site_code in ('149','230') and year(period_end)=2026 union all select source_lane, source_site_code, period_end, category from DEV_G2M_AI.SEMANTIC.SEM_AI_INCOME_STATEMENT_FORECAST where source_lane='HERSHA' and source_site_code in ('149','230') and year(period_end)=2026)
order by 1;
